        {
          "datasource": {
            "type": "influxdb",
            "uid": "ea0c4e40-913a-457e-bc0b-15de88531c0c"
          },
          "refId": "A"
        }
      ],
      "title": "Summary",
      "type": "row"
    },
    {
      "datasource": {
        "type": "influxdb",
        "uid": "$data_source"
      },
      "description": "",
      "fieldConfig": {
        "defaults": {
          "mappings": [
            {
              "options": {
                "match": "null",
                "result": {
                  "text": "N/A"
                }
              },
              "type": "special"
            }
          ],
          "thresholds": {
            "mode": "absolute",
            "steps": [
              {
                "color": "green",
                "value": null
              },
              {
                "color": "red",
                "value": 80
              }
            ]
          },
          "unit": "none"
        },
        "overrides": []
      },
      "gridPos": {
        "h": 5,
        "w": 4,
        "x": 0,
        "y": 1
      },
      "id": 44,
      "links": [],
      "maxDataPoints": 100,
      "options": {
        "colorMode": "value",
        "graphMode": "area",
        "justifyMode": "auto",
        "orientation": "horizontal",
        "reduceOptions": {
          "calcs": [
            "lastNotNull"
          ],
          "fields": "",
          "values": false
        },
        "textMode": "value"
      },
      "pluginVersion": "10.1.0",
      "targets": [
        {
          "datasource": {
            "uid": "$data_source"
          },
          "dsType": "influxdb",
          "groupBy": [],
          "hide": false,
          "measurement": "/^$measurement_name$/",
          "orderByTime": "ASC",
          "policy": "default",
          "query": "SELECT last(\"minAT\") FROM /^$measurement_name$/ WHERE (\"application\" =~ /^$application$/) AND $timeFilter",
          "rawQuery": true,
          "refId": "A",
          "resultFormat": "time_series",
          "select": [
            [
              {
                "params": [
                  "meanAT"
                ],
                "type": "field"
              },
              {
                "params": [],
                "type": "last"
              }
            ]
          ],
          "tags": [
            {
              "key": "application",
              "operator": "=~",
              "value": "/^$application$/"
            }
          ]
        },
        {
          "datasource": {
            "uid": "$data_source"
          },
          "dsType": "influxdb",
          "groupBy": [],
          "hide": true,
          "measurement": "/^$measurement_name$/",
          "orderByTime": "ASC",
          "policy": "default",
