{
  "apiVersion": 1,
  "datasources": [
    {
      "name": "Prometheus",
      "type": "prometheus",
      "uid": "prometheus",
      "access": "proxy",
      "url": "http://prometheus:9090",
      "isDefault": true,
      "editable": false,
      "jsonData": {
        "httpMethod": "POST",
        "exemplarTraceIdDestinations": [
          {
            "name": "traceID",
            "datasourceUid": "tempo"
          }
        ]
      }
    },
    {
      "name": "Loki",
      "type": "loki",
      "uid": "loki",
      "access": "proxy",
      "url": "http://loki:3100",
      "isDefault": false,
      "editable": false,
      "jsonData": {
        "derivedFields": [
          {
            "name": "trace_id",
            "matcherRegex": "\"trace_id\"\\s*:\\s*\"([0-9a-f]+)\"",
            "datasourceUid": "tempo",
            "url": "$${__value.raw}"
          }
        ]
      }
    },
    {
      "name": "Tempo",
      "type": "tempo",
      "uid": "tempo",
      "access": "proxy",
      "url": "http://tempo:3200",
      "isDefault": false,
      "editable": false,
      "jsonData": {
        "nodeGraph": {
          "enabled": true
        },
        "tracesToLogsV2": {
          "datasourceUid": "loki",
          "filterByTraceID": true,
          "tags": [
            {
              "key": "service.name",
              "value": "service_name"
            }
          ]
        },
        "tracesToMetrics": {
          "datasourceUid": "prometheus",
          "tags": [
            {
              "key": "service.name",
              "value": "service_name"
            }
          ]
        },
        "serviceMap": {
          "datasourceUid": "prometheus"
        },
        "tracesToProfilesV2": {
          "datasourceUid": "pyroscope",
          "profileTypeId": "process_cpu:cpu:nanoseconds:cpu:nanoseconds",
          "tags": [
            {
              "key": "service.name",
              "value": "service_name"
            }
          ]
        }
      }
    },
    {
      "name": "Pyroscope",
      "type": "grafana-pyroscope-datasource",
      "uid": "pyroscope",
      "access": "proxy",
      "url": "http://pyroscope:4040",
      "isDefault": false,
      "editable": false,
      "jsonData": {}
    },
    {
      "name": "Alertmanager",
      "type": "alertmanager",
      "uid": "alertmanager",
      "access": "proxy",
      "url": "http://alertmanager:9093",
      "isDefault": false,
      "editable": false,
      "jsonData": {
        "implementation": "prometheus",
        "handleGrafanaManagedAlerts": false
      }
    }
  ]
}
